def transform(grid):
    """Find unique non-zero value v. Cells with v become 0. Others become v // 3."""
    if not grid or not grid[0]:
        return grid.copy()

    h, w = len(grid), len(grid[0])

    # Find unique non-zero value
    v = None
    for row in grid:
        for cell in row:
            if cell != 0 and v is None:
                v = cell
            elif cell != 0 and cell != v:
                # Multiple non-zero values - should not happen per problem constraints
                return grid

    if v is None:
        return [row[:] for row in grid]

    output_val = v // 3

    # Create new grid properly
    result = []
    for i in range(h):
        row = [0] * w
        for j in range(w):
            if grid[i][j] == v:
                row[j] = 0
            else:
                row[j] = output_val
        result.append(row)

    return result

